// Formule finale d'un attribut :
// (base + SOMME_ADDITION)
//   × (1 + SOMME_MULTIPLY_BASE)
//   × (1 + MT_1) × (1 + MT_2) × ...

private static final UUID DMG_UUID =
    UUID.fromString("58e71cd2-e8be-4ee3-b8e0-0c5c3d3e4051");

@Override
public Multimap<Attribute, AttributeModifier> getAttributeModifiers(
        EquipmentSlot slot, ItemStack stack) {
    ImmutableMultimap.Builder<Attribute, AttributeModifier> b =
        ImmutableMultimap.builder();
    b.putAll(super.getAttributeModifiers(slot, stack));
    if (slot == EquipmentSlot.MAINHAND)
        b.put(Attributes.ATTACK_DAMAGE,
              new AttributeModifier(DMG_UUID, "Bonus", 8.0, Operation.ADDITION));
    return b.build();
}

public class MonEffet extends MobEffect {
    public MonEffet() {
        super(MobEffectCategory.BENEFICIAL, 0x00FF88); // catégorie, couleur ARGB
    }

    @Override
    public void applyEffectTick(LivingEntity entity, int amplifier) {
        entity.heal(1.0f); // soigner 0.5 PV toutes les 40 ticks
    }

    @Override
    public boolean isDurationEffectTick(int duration, int amplifier) {
        return duration % 40 == 0; // fréquence d'application
    }
}

@SubscribeEvent
public static void onRegisterCommands(RegisterCommandsEvent event) {
    CommandDispatcher<CommandSourceStack> dispatcher = event.getDispatcher();
    dispatcher.register(
        Commands.literal("cmd")
            .requires(src -> src.hasPermission(2))
            .then(Commands.argument("n", IntegerArgumentType.integer(1, 64))
                .executes(ctx -> {
                    int n = IntegerArgumentType.getInteger(ctx, "n");
                    // ... logique ...
                    return 1; // 1 = succès
                }))
    );
}

@SubscribeEvent
public static void onFov(ComputeFovModifierEvent event) {
    if (event.getPlayer().hasEffect(ModEffects.MON_EFFET.get()))
        event.setNewFovModifier(event.getNewFovModifier() * 0.85f);
}

@SubscribeEvent
public static void onCamera(ViewportEvent.ComputeCameraAngles event) {
    event.setRoll(15f);   // incliner l'écran (en degrés)
    // event.setYaw(...) / event.setPitch(...) aussi disponibles
}

@SubscribeEvent
public static void onOverlayPre(RenderGuiOverlayEvent.Pre event) {
    if (event.getOverlay() == VanillaGuiOverlay.HOTBAR.type()) {
        event.setCanceled(true); // supprimer le HUD vanilla
        // dessiner le sien à la place avec GuiGraphics event.getGuiGraphics()
    }
}

// Dans RegisterGuiOverlaysEvent (Mod bus) :
@SubscribeEvent
public static void onRegisterOverlays(RegisterGuiOverlaysEvent event) {
    event.registerAboveAll("mon_hud", MON_OVERLAY);
    // MON_OVERLAY implémente IGuiOverlay :
    // (gui, graphics, partialTick, w, h) -> { graphics.drawString(...) }
}

// Dessiner dans un overlay ou un Screen :
GuiGraphics g = ...;
g.drawString(font, "Texte", x, y, 0xFFFFFF, false);
g.blit(texture, x, y, u, v, w, h);       // sprite depuis une texture
g.fill(x1, y1, x2, y2, 0x80000000);      // rectangle semi-transparent
g.renderItem(stack, x, y);               // rendu de l'icône d'un item

// Côté serveur :
NetworkHooks.openScreen(
