// MenuProvider :
// Component getDisplayName() + AbstractContainerMenu createMenu(id, inv, player)

public class MonMenu extends AbstractContainerMenu {
    public MonMenu(int windowId, Inventory playerInv) {
        super(ModMenuTypes.MON_MENU.get(), windowId);
        // ajouter les slots du joueur (3×9 + barre d'action) :
        for (int row = 0; row < 3; row++)
            for (int col = 0; col < 9; col++)
                this.addSlot(new Slot(playerInv, col + row*9+9, 8+col*18, 84+row*18));
        for (int col = 0; col < 9; col++)
            this.addSlot(new Slot(playerInv, col, 8+col*18, 142));
    }

    @Override public boolean stillValid(Player p) { return true; }
}

// Slot qui n'accepte qu'un type d'item :
this.addSlot(new Slot(containerData, 0, 56, 35) {
    @Override public boolean mayPlace(ItemStack stack) {
        return stack.is(ModItems.RUBY.get());
    }
    @Override public int getMaxStackSize() { return 1; }
});

public class MonScreen extends AbstractContainerScreen<MonMenu> {
    private static final ResourceLocation TEXTURE =
        new ResourceLocation("monmod", "textures/gui/mon_gui.png");

    public MonScreen(MonMenu menu, Inventory inv, Component title) {
        super(menu, inv, title);
        this.imageWidth = 176; this.imageHeight = 166;
    }

    @Override
    protected void renderBg(GuiGraphics g, float partial, int mx, int my) {
        g.blit(TEXTURE, leftPos, topPos, 0, 0, imageWidth, imageHeight);
    }
}

// Déclarer (dans la classe client ou ModEvents) :
public static KeyMapping TOUCHE =
    new KeyMapping("key.monmod.nom",
                   GLFW.GLFW_KEY_G,
                   "key.categories.monmod");

// Enregistrer (Mod bus, RegisterKeyMappingsEvent) :
@SubscribeEvent
public static void onRegisterKeys(RegisterKeyMappingsEvent event) {
    event.register(TOUCHE);
}

// Dans ClientTickEvent :
