    if (event.phase == TickEvent.Phase.END) {
        while (MonKeys.TOUCHE.consumeClick()) {
            // envoyer un paquet au serveur ou déclencher l'action locale
        }
    }
}

// Uniquement côté CLIENT (ne jamais appeler côté serveur)
Minecraft mc = Minecraft.getInstance();
LocalPlayer player = mc.player;     // joueur local
ClientLevel level  = mc.level;      // monde local
mc.font;                            // police de caractères
mc.getTextureManager();             // gestionnaire de textures

// Ouvrir un Screen depuis le client :
Minecraft.getInstance().setScreen(new MonInfoScreen(...));
// Fermer un Screen :
Minecraft.getInstance().setScreen(null);

@SubscribeEvent
public static void onGatherData(GatherDataEvent event) {
    DataGenerator gen = event.getGenerator();
    PackOutput out = gen.getPackOutput();
    ExistingFileHelper efh = event.getExistingFileHelper();

    // Ajouter un provider :
    gen.addProvider(event.includeServer(),
        new MonLootTableProvider(out));
    gen.addProvider(event.includeClient(),
        new MonItemModelProvider(out, efh));
}
